input.command:
$roots = @("$HOME\Desktop\DEV", "$HOME\Desktop\DEV\Football", "$HOME\Desktop\DEV\SpecialRequests")
$skip = @('.claude','_tools','_DRIVE','token-dashboard')
$out = @()
foreach ($r in $roots) {
  if (-not (Test-Path $r)) { continue }
  foreach ($d in Get-ChildItem $r -Directory -ErrorAction SilentlyContinue) {
    if ($skip -contains $d.Name) { continue }
    if ($d.Name -like '*_OLD_merged*') { continue }
    if ($d.Name -eq 'Football' -or $d.Name -eq 'SpecialRequests') { continue }
    if (-not (Test-Path "$($d.FullName)\.git")) { $out += [pscustomobject]@{Path=$d.FullName;Name=$d.Name;State='NOT_A_REPO';Dirty=0;Unpushed=0;Remote=''}; continue }
    Push-Location $d.FullName
    $remote = (git remote get-url origin 2>$null)
    $dirty = @(git status --porcelain 2>$null).Count
    $branch = (git rev-parse --abbrev-ref HEAD 2>$null)
    $unpushed = 0
    if ($remote) { $u = (git rev-list --count "origin/$branch..HEAD" 2>$null); if ($u) { $unpushed = [int]$u } }
    $state = if ($remote) { 'REPO_REMOTE' } else { 'REPO_NO_REMOTE' }
    $out += [pscustomobject]@{Path=$d.FullName;Name=$d.Name;State=$state;Dirty=$dirty;Unpushed=$unpushed;Remote=$remote}
    Pop-Location
  }
}
$out | ConvertTo-Json -Compress | Out-File "$env:CLAUDE_JOB_DIR\tmp\inv.json" -Encoding utf8
"TOTAL: $($out.Count)"
"NOT_A_REPO: $(@($out | ? State -eq 'NOT_A_REPO').Count)"
"NO_REMOTE: $(@($out | ? State -eq 'REPO_NO_REMOTE').Count)"
"DIRTY: $(@($out | ? {$_.Dirty -gt 0}).Count)"
"UNPUSHED: $(@($out | ? {$_.Unpushed -gt 0}).Count)"
"--- needs attention ---"
$out | ? { $_.State -ne 'REPO_REMOTE' -or $_.Dirty -gt 0 -or $_.Unpushed -gt 0 } | % { "$($_.Name)`t$($_.State)`tdirty=$($_.Dirty)`tunpushed=$($_.Unpushed)" }

cd "$HOME\Desktop\DEV"
"=== SpecialRequests/docs tracked anywhere? ==="
git check-ignore -v "SpecialRequests/docs/STATUS.md" 2>&1
"=== gh repos with no local folder ==="
$remote = (gh repo list erash11 --limit 300 --json name | ConvertFrom-Json).name
$skipRepos = @('dotclaude','SecondBrain','claude-skills','claude-memory-compiler','DEV','DexaProject')
$local = @{}
foreach ($r in @("$HOME\Desktop\DEV","$HOME\Desktop\DEV\Football","$HOME\Desktop\DEV\SpecialRequests")) {
  Get-ChildItem $r -Directory -ErrorAction SilentlyContinue | % { $local[$_.Name] = $true }
}
"remote repo count: $($remote.Count)"
$missing = $remote | ? { $skipRepos -notcontains $_ -and -not $local.ContainsKey($_) }
if ($missing) { "MISSING LOCALLY:"; $missing | % { "  $_" } } else { "MISSING LOCALLY: none" }

foreach ($n in @('AppliedPerformance-Site','KnowledgeManagement','Gemini_Projects','SignalPlays')) {
  $hits = Get-ChildItem "$HOME\Desktop\DEV" -Directory -Recurse -Depth 3 -Filter $n -ErrorAction SilentlyContinue
  $arch = Get-ChildItem "$HOME\Desktop\DEV\_ARCHIVE" -Directory -Recurse -Depth 2 -Filter $n -ErrorAction SilentlyContinue
  "$n -> " + $(if ($hits -or $arch) { (@($hits)+@($arch) | % FullName) -join '; ' } else { 'NOT FOUND on disk' })
}

cd "$HOME\Desktop\DEV"
foreach ($n in @('AppliedPerformance-Site','KnowledgeManagement','Gemini_Projects')) {
  gh repo clone "erash11/$n" "$HOME\Desktop\DEV\$n" 2>&1 | Select-Object -Last 2
  if (Test-Path "$HOME\Desktop\DEV\$n\.git") {
    $c = @(Get-ChildItem "$HOME\Desktop\DEV\$n" -Recurse -File -ErrorAction SilentlyContinue).Count
    $last = git -C "$HOME\Desktop\DEV\$n" log -1 --format='%ad %s' --date=short
    "OK $n : $c files | last: $last"
  } else { "FAILED $n" }
}

foreach ($n in @('KeystoneOS','SportScienceResearchRepo','Travel_Map')) {
  $p = Get-ChildItem "$HOME\Desktop\DEV" -Directory -Recurse -Depth 2 -Filter $n -ErrorAction SilentlyContinue | Select-Object -First 1
  if ($p) { "$n`t" + (git -C $p.FullName log -1 --format='%ai') }
}
"=== VERIFY re-walk ==="
$roots = @("$HOME\Desktop\DEV", "$HOME\Desktop\DEV\Football", "$HOME\Desktop\DEV\SpecialRequests")
$skip = @('.claude','_tools','_DRIVE','token-dashboard','Football','SpecialRequests')
$bad = @(); $n = 0
foreach ($r in $roots) {
  foreach ($d in Get-ChildItem $r -Directory -ErrorAction SilentlyContinue) {
    if ($skip -contains $d.Name -or $d.Name -like '*_OLD_merged*') { continue }
    if (-not (Test-Path "$($d.FullName)\.git")) { if ($d.Name -ne '_to_delete' -and $d.Name -ne 'docs') { $bad += "$($d.Name): not a repo" }; continue }
    $n++
    $dirty = @(git -C $d.FullName status --porcelain 2>$null).Count
    $br = git -C $d.FullName rev-parse --abbrev-ref HEAD 2>$null
    $up = git -C $d.FullName rev-list --count "origin/$br..HEAD" 2>$null
    if ($dirty -gt 0) { $bad += "$($d.Name): $dirty dirty" }
    if ($up -and [int]$up -gt 0) { $bad += "$($d.Name): $up unpushed" }
  }
}
"repos verified: $n"
if ($bad) { "ISSUES:"; $bad | % { "  $_" } } else { "ISSUES: none - all clean and pushed" }
"from-* files created this run: $(@(Get-ChildItem "$HOME\Desktop\DEV" -Recurse -Filter '*.from-mac' -ErrorAction SilentlyContinue).Count)"

"=== what are the 08:52:28 commits? ==="
foreach ($n in @('SportScienceResearchRepo','Travel_Map')) {
  $p = Get-ChildItem "$HOME\Desktop\DEV" -Directory -Recurse -Depth 2 -Filter $n -ErrorAction SilentlyContinue | Select-Object -First 1
  "$n : " + (git -C $p.FullName log -1 --format='%s')
}
"=== KeystoneOS last ==="
git -C "$HOME\Desktop\DEV\KeystoneOS" log -1 --format='%s'
"=== .from-mac files (pre-existing, none created this run) ==="
Get-ChildItem "$HOME\Desktop\DEV" -Recurse -Filter '*.from-mac' -ErrorAction SilentlyContinue | % { $_.FullName.Replace("$HOME\Desktop\DEV\","") + "  (" + $_.LastWriteTime.ToString('yyyy-MM-dd') + ")" }

$roots = @("$HOME\Desktop\DEV", "$HOME\Desktop\DEV\Football", "$HOME\Desktop\DEV\SpecialRequests")
$skip = @('.claude','_tools','_DRIVE','token-dashboard','Football','SpecialRequests','_to_delete','docs')
$repos = @()
foreach ($r in $roots) { foreach ($d in Get-ChildItem $r -Directory -EA SilentlyContinue) {
  if ($skip -contains $d.Name -or $d.Name -like '*_OLD_merged*') { continue }
  if (Test-Path "$($d.FullName)\.git") { $repos += $d.FullName } } }
"fetching $($repos.Count) repos..."
$behind = @()
foreach ($p in $repos) {
  git -C $p fetch origin --quiet 2>$null
  $br = git -C $p rev-parse --abbrev-ref HEAD 2>$null
  $b = git -C $p rev-list --count "HEAD..origin/$br" 2>$null
  $a = git -C $p rev-list --count "origin/$br..HEAD" 2>$null
  if (($b -and [int]$b -gt 0) -or ($a -and [int]$a -gt 0)) {
    $behind += [pscustomobject]@{Path=$p;Name=(Split-Path $p -Leaf);Branch=$br;Behind=[int]$b;Ahead=[int]$a}
  }
}
if ($behind) { "--- OUT OF SYNC ---"; $behind | % { "$($_.Name)`tbehind=$($_.Behind)`tahead=$($_.Ahead)" } } else { "--- all 135 already up to date with origin ---" }

$names = @('2025-11-25_EOS_Football_Analysis_GPS_ERR','B_Ellis','CFB_Forecast_Archive','CFB_Victory_Model','claude-global-memory','CommandCentre','graphify-out','KeystoneOS','MatchupAnalysis_FB2026','May_Meetings_Research','project-triage','RTP_Constraints_Course','S2_Evaluation','SoftwareTech_Mgmt_Framework','Weekly_Matchups_2026')
$ok=0; $fail=@()
foreach ($n in $names) {
  $p = Get-ChildItem "$HOME\Desktop\DEV" -Directory -Recurse -Depth 2 -Filter $n -EA SilentlyContinue | Select-Object -First 1
  if (-not $p) { $fail += "$n : not found"; continue }
  $br = git -C $p.FullName rev-parse --abbrev-ref HEAD 2>$null
  $r = git -C $p.FullName merge --ff-only "origin/$br" 2>&1
  if ($LASTEXITCODE -eq 0) { $ok++; "$n -> OK ($br)" } else { $fail += "$n : $r" }
}
"merged: $ok / $($names.Count)"
if ($fail) { "FAILED:"; $fail | % { "  $_" } }

$roots = @("$HOME\Desktop\DEV", "$HOME\Desktop\DEV\Football", "$HOME\Desktop\DEV\SpecialRequests")
$skip = @('.claude','_tools','_DRIVE','token-dashboard','Football','SpecialRequests','_to_delete','docs')
$bad=@(); $n=0
foreach ($r in $roots) { foreach ($d in Get-ChildItem $r -Directory -EA SilentlyContinue) {
  if ($skip -contains $d.Name -or $d.Name -like '*_OLD_merged*') { continue }
  if (-not (Test-Path "$($d.FullName)\.git")) { $bad += "$($d.Name): NOT A REPO"; continue }
  $n++
  $br = git -C $d.FullName rev-parse --abbrev-ref HEAD 2>$null
  $dirty = @(git -C $d.FullName status --porcelain 2>$null).Count
  $b = git -C $d.FullName rev-list --count "HEAD..origin/$br" 2>$null
  $a = git -C $d.FullName rev-list --count "origin/$br..HEAD" 2>$null
  if ($dirty -gt 0) { $bad += "$($d.Name): $dirty dirty" }
  if ($b -and [int]$b -gt 0) { $bad += "$($d.Name): still behind $b" }
  if ($a -and [int]$a -gt 0) { $bad += "$($d.Name): unpushed $a" }
} }
"repos verified against fresh origin: $n"
if ($bad) { "REMAINING:"; $bad | % { "  $_" } } else { "REMAINING: none" }
"--- config repos ---"
foreach ($c in @("$HOME\.claude","$HOME\.claude\skills","$HOME\.claude\global-memory")) {
  $br = git -C $c rev-parse --abbrev-ref HEAD 2>$null
  git -C $c fetch origin --quiet 2>$null
  "$(Split-Path $c -Leaf): dirty=$(@(git -C $c status --porcelain).Count) behind=$(git -C $c rev-list --count HEAD..origin/$br) ahead=$(git -C $c rev-list --count origin/$br..HEAD)"
}

"KeystoneOS newest now: " + (git -C "$HOME\Desktop\DEV\KeystoneOS" log -1 --format='%ad %s' --date=short)
"KeystoneOS STATUS.md still stub? Next-section content:"
(Get-Content "$HOME\Desktop\DEV\KeystoneOS\docs\STATUS.md" -Raw) -split "## Next" | Select-Object -Last 1 | % { $_.Trim().Substring(0,[Math]::Min(200,$_.Trim().Length)) }
"dirty .claude paths:"; git -C "$HOME\.claude" status --porcelain | % { $_ }

$p = "$HOME\Desktop\DEV\project-triage"
foreach ($pair in @(@('portfolio.json','portfolio.json.from-mac'), @('2026-05-22.html','2026-05-22.html.from-mac'))) {
  $a = Join-Path $p $pair[0]; $b = Join-Path $p $pair[1]
  "=== $($pair[0]) ==="
  "  live exists: $(Test-Path $a)  size=$((Get-Item $a -EA SilentlyContinue).Length)  mtime=$((Get-Item $a -EA SilentlyContinue).LastWriteTime)"
  "  from-mac    : $(Test-Path $b)  size=$((Get-Item $b -EA SilentlyContinue).Length)  mtime=$((Get-Item $b -EA SilentlyContinue).LastWriteTime)"
  if ((Test-Path $a) -and (Test-Path $b)) {
    $h1 = (Get-FileHash $a).Hash; $h2 = (Get-FileHash $b).Hash
    "  identical: $($h1 -eq $h2)"
    if ($h1 -ne $h2) { "  --- diff (first 25 lines) ---"; git -C $p diff --no-index -- $pair[0] $pair[1] 2>&1 | Select-Object -First 25 }
  }
}

